def main(data: str) -> dict:
    import json

    try:
        if isinstance(data, dict):
            obj = data
        elif isinstance(data, str):
            text = data.strip()
            if not text:
                raise ValueError("data为空")
            obj = json.loads(text)
        else:
            raise TypeError("data必须是JSON字符串或Object")

        if not isinstance(obj, dict):
            raise TypeError("data解析结果必须是Object")

        return {
            "parsed_data": obj,
            "parse_ok": True,
            "parse_err": ""
        }
    except Exception as exc:
        return {
            "parsed_data": {},
            "parse_ok": False,
            "parse_err": str(exc)
        }

def main(parsed_data: dict) -> dict:
    import re
    from datetime import datetime

    errors = []
    warnings = []
    checks = []
    cn_re = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]")
    en_re = re.compile(r"[A-Za-z]")

    def is_num(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    def add_check(name, passed, detail=""):
        checks.append({"检查项": name, "是否通过": bool(passed), "说明": detail})

    def validate_keys(value, path="根"):
        if isinstance(value, dict):
            for key, child in value.items():
                key_text = str(key)
                current = f"{path}.{key_text}"
                if not cn_re.search(key_text):
                    errors.append(f"键名必须包含中文：{current}")
                if en_re.search(key_text):
                    errors.append(f"键名不得含英文字母：{current}")
                validate_keys(child, current)
        elif isinstance(value, list):
            for index, child in enumerate(value):
                validate_keys(child, f"{path}[{index}]")

    def parse_time(value):
        text = str(value or "").strip()
        for fmt in ("%H:%M:%S", "%H:%M"):
            try:
                parsed = datetime.strptime(text, fmt)
                return parsed.hour * 3600 + parsed.minute * 60 + parsed.second
            except ValueError:
                pass
        raise ValueError(f"非法时刻：{text}")

    def close_enough(left, right, tolerance):
        return abs(float(left) - float(right)) <= tolerance

    if not isinstance(parsed_data, dict):
        errors.append("输入必须为Object")
    else:
        validate_keys(parsed_data)

    required_groups = [
        "预测方案信息", "项目背景", "新线基础信息", "新线客流预测数据",
        "既有线路客流及运能数据", "行车组织基础及专业方案",
        "首末班车及换乘衔接数据", "车站客运能力数据",
        "车辆乘务及人员资源数据", "设备及应急保障数据", "外部交通衔接数据"
    ]
    for name in required_groups:
        if name not in parsed_data:
            errors.append(f"缺少顶层数据组：{name}")

    if not errors:
        scheme = parsed_data["预测方案信息"]
        line = parsed_data["新线基础信息"]
        passenger = parsed_data["新线客流预测数据"]
        network = parsed_data["既有线路客流及运能数据"]
        operation = parsed_data["行车组织基础及专业方案"]
        first_last = parsed_data["首末班车及换乘衔接数据"]
        station_cap = parsed_data["车站客运能力数据"]
        resource = parsed_data["车辆乘务及人员资源数据"]
        equipment = parsed_data["设备及应急保障数据"]

        for field in ["方案编号", "方案名称", "方案状态", "预测开始日期", "预测结束日期"]:
            if scheme.get(field) in (None, ""):
                errors.append(f"预测方案信息.{field}不能为空")
        if scheme.get("主方案标记") is not True:
            errors.append("预测方案信息.主方案标记必须为true")

        stations = line.get("车站信息", [])
        declared_station_count = line.get("车站数量_座")
        station_names = [x.get("车站名称") for x in stations if isinstance(x, dict)]
        sequence_values = [x.get("序号") for x in stations if isinstance(x, dict)]
        station_count_ok = is_num(declared_station_count) and int(declared_station_count) == len(stations)
        add_check("车站数量闭合", station_count_ok, f"声明{declared_station_count}座，明细{len(stations)}座")
        if not station_count_ok:
            errors.append("新线基础信息.车站数量与车站信息明细不一致")
        if len(station_names) != len(set(station_names)) or any(not x for x in station_names):
            errors.append("车站名称必须非空且唯一")
        if sequence_values != list(range(1, len(stations) + 1)):
            errors.append("车站序号必须从1连续递增")

        transfer_count = sum(1 for x in stations if x.get("换乘线路"))
        transfer_ok = transfer_count == line.get("换乘站数量_座")
        add_check("换乘站数量闭合", transfer_ok, f"声明{line.get('换乘站数量_座')}座，明细{transfer_count}座")
        if not transfer_ok:
            errors.append("换乘站数量与车站换乘关系不一致")

        workday_total = next(
            (x.get("日均客运量_人次") for x in passenger.get("线路总体客流", []) if x.get("日期类型") == "工作日"),
            None
        )
        station_total = sum(x.get("工作日日均客运量_人次", 0) for x in stations if is_num(x.get("工作日日均客运量_人次", 0)))
        total_tolerance = max(100, float(workday_total or 0) * 0.005)
        total_ok = is_num(workday_total) and close_enough(station_total, workday_total, total_tolerance)
        add_check("工作日车站客流汇总闭合", total_ok, f"车站合计{station_total}人次，线路值{workday_total}人次")
        if not total_ok:
            warnings.append("工作日车站客流合计与线路日均客运量超出0.5%容差")

        for row in network.get("线路日均客运量对比", []):
            before = row.get("开通前_人次")
            after = row.get("开通后_人次")
            change = row.get("变化量_人次")
            rate = row.get("变化率_百分数")
            if not all(is_num(x) for x in [before, after, change, rate]):
                errors.append(f"{row.get('线路名称')}日均客运量对比存在非数值字段")
                continue
            if not close_enough(after - before, change, 1):
                errors.append(f"{row.get('线路名称')}日均客运量变化量不闭合")
            expected_rate = 0 if before == 0 else change / before * 100
            if not close_enough(expected_rate, rate, 0.05):
                warnings.append(f"{row.get('线路名称')}日均客运量变化率存在舍入差异")

        for row in network.get("既有线运能匹配", []):
            flow = row.get("断面客流_人次每小时")
            capacity = row.get("小时运力_人次")
            rate = row.get("满载率_百分数")
            if not all(is_num(x) for x in [flow, capacity, rate]) or capacity <= 0:
                errors.append(f"{row.get('线路名称')}运能匹配记录非法")
                continue
            expected_rate = flow / capacity * 100
            if not close_enough(expected_rate, rate, 0.06):
                warnings.append(f"{row.get('线路名称')}满载率与客流、运力存在舍入差异")

        min_gap = operation.get("线路技术条件", {}).get("最小追踪间隔_秒")
        max_online = 0
        for row in operation.get("分时运行方案", []):
            max_online = max(max_online, int(row.get("上线列车数_列", 0) or 0))
            for field in ["核心区段行车间隔_秒", "外围区段行车间隔_秒"]:
                gap = row.get(field)
                if not is_num(gap) or not is_num(min_gap) or gap < min_gap:
                    errors.append(f"{row.get('日期类型')}{row.get('时段')}{field}小于技术约束或类型非法")

        vehicles = resource.get("车辆资源", {})
        vehicle_close = vehicles.get("可上线列车数_列", 0) + vehicles.get("检修及轮换列车数_列", 0) == vehicles.get("调试合格列车数_列", 0)
        reserve_close = vehicles.get("备用图最大上线列车数_列", 0) + vehicles.get("计划备用列车数_列", 0) <= vehicles.get("可上线列车数_列", 0)
        add_check("车辆数量闭合", vehicle_close, "可上线列车数+检修及轮换列车数=调试合格列车数")
        add_check("备用图车辆闭合", reserve_close, "备用图上线列车数+备用车不超过可上线列车数")
        if not vehicle_close or not reserve_close or max_online > vehicles.get("基本图最大上线列车数_列", 0):
            errors.append("车辆资源不能闭合基本图、备用图和检修轮换需求")

        drivers = resource.get("司机资源", {})
        driver_close = drivers.get("高客流备用图最大需求人数", 0) + drivers.get("备班人数", 0) <= drivers.get("培训及取证合格人数", 0)
        add_check("司机资源闭合", driver_close, "备用图需求人数+备班人数不超过取证合格人数")
        if not driver_close:
            errors.append("司机资源不足以兑现高客流备用图及备班安排")

        walk_seconds = first_last.get("换乘走行时间_分钟", 0) * 60
        for row in first_last.get("重点首班换乘衔接", []):
            try:
                arrival = parse_time(row.get("到达时刻"))
                departure = parse_time(row.get("换入首班车时刻"))
                elapsed = (departure - arrival) % 86400 - walk_seconds
                if abs(elapsed - row.get("等待时间_秒", 0)) > 1:
                    errors.append(f"{row.get('换乘站')}首班换乘等待时间不闭合")
            except Exception as exc:
                errors.append(str(exc))

        density_standard = station_cap.get("站台密度控制标准_人每平方米")
        for row in station_cap.get("重点换乘站预测", []):
            density = row.get("最高预测站台密度_人每平方米")
            if not is_num(density) or not is_num(density_standard) or density < 0:
                errors.append(f"{row.get('车站名称')}站台密度记录非法")
            elif density > density_standard:
                warnings.append(f"{row.get('车站名称')}预测站台密度超过控制标准")

        facility_names = {x.get("车站名称") for x in station_cap.get("重点车站设施能力", [])}
        forecast_names = {x.get("车站名称") for x in station_cap.get("重点换乘站预测", [])}
        if facility_names != forecast_names:
            errors.append("重点换乘站预测与设施能力记录无法按车站名称一一关联")

        for row in equipment.get("设备系统状态", []):
            availability = row.get("可用率_百分数")
            issue_count = row.get("影响开通遗留问题数量")
            if not is_num(availability) or not 0 <= availability <= 100:
                errors.append(f"{row.get('设备系统')}可用率必须在0—100之间")
            if not is_num(issue_count) or issue_count < 0:
                errors.append(f"{row.get('设备系统')}遗留问题数量必须为非负数")

    return {
        "is_valid": len(errors) == 0,
        "error_list": errors,
        "warn_list": warnings,
        "check_list": checks
    }

