def main(metric_result: dict) -> dict:
    import json

    warnings = []
    limit = 12000

    def compact(value, list_limit=20, depth=0):
        if depth > 7:
            return None
        if isinstance(value, dict):
            result = {}
            for key, child in value.items():
                if key == "事实" and isinstance(child, list):
                    ranked = sorted(child, key=lambda x: int(x.get("优先级", 0)), reverse=True)
                    result[key] = [compact(x, list_limit, depth + 1) for x in ranked[:list_limit]]
                else:
                    result[key] = compact(child, list_limit, depth + 1)
            return result
        if isinstance(value, list):
            return [compact(x, list_limit, depth + 1) for x in value[:list_limit]]
        if isinstance(value, str):
            return value[:500]
        return value

    def serialize(name, value):
        text = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
        if len(text) <= limit:
            return text
        reduced = compact(value, list_limit=12)
        text = json.dumps(reduced, ensure_ascii=False, separators=(",", ":"))
        if len(text) > limit:
            reduced = compact(value, list_limit=6)
            text = json.dumps(reduced, ensure_ascii=False, separators=(",", ":"))
        if len(text) > limit:
            raise ValueError(f"{name}压缩后仍超过{limit}字符")
        warnings.append(f"{name}因超过{limit}字符已按优先级压缩普通明细")
        return text

    task = metric_result.get("任务上下文", {})
    passenger = metric_result.get("客流及线网影响", {})
    operation = metric_result.get("行车组织", {})
    service = metric_result.get("首末班与车站服务", {})
    guard = metric_result.get("运营保障与风险", {})

    summary_source = {
        "任务上下文": task,
        "线路基本情况": passenger.get("指标", {}).get("线路基本情况", {}),
        "总体客流": passenger.get("指标", {}).get("总体客流", {}),
        "区段客流": passenger.get("指标", {}).get("区段客流", {}),
        "既有线运能关注": passenger.get("指标", {}).get("既有线运能匹配", [])[:6],
        "行车核心配置": {
            "交路定义": operation.get("指标", {}).get("交路定义", {}),
            "分时运行方案": operation.get("指标", {}).get("分时运行方案", []),
            "备用车安排": operation.get("指标", {}).get("备用车安排", []),
            "高客流备用运行图": operation.get("指标", {}).get("高客流备用运行图", [])
        },
        "首末班核心配置": {
            "首班车": service.get("指标", {}).get("首班车", []),
            "末班车": service.get("指标", {}).get("末班车", [])
        },
        "保障核心指标": {
            "车辆余量_列": guard.get("指标", {}).get("车辆余量_列"),
            "司机余量_人": guard.get("指标", {}).get("司机余量_人"),
            "最低设备可用率_百分数": guard.get("指标", {}).get("最低设备可用率_百分数"),
            "影响开通遗留问题合计": guard.get("指标", {}).get("影响开通遗留问题合计")
        }
    }

    return {
        "passenger_packet": serialize("客流专题包", {"任务上下文": task, "专题结果": passenger}),
        "ops_packet": serialize("行车专题包", {"任务上下文": task, "专题结果": operation, "既有线运能": passenger.get("指标", {}).get("既有线运能匹配", [])}),
        "service_packet": serialize("服务专题包", {"任务上下文": task, "专题结果": service}),
        "guard_packet": serialize("保障专题包", {"任务上下文": task, "专题结果": guard, "行车资源闭合": {"车辆余量_列": operation.get("指标", {}).get("备用图车辆余量_列"), "司机余量_人": operation.get("指标", {}).get("备用图司机余量_人")}}),
        "summary_packet": serialize("综合专题包", summary_source),
        "pack_warns": warnings
    }

def main(metric_result: dict) -> dict:
    import json

    topic_map = {
        "客流及线网影响": ("客流", "证据-客流"),
        "行车组织": ("行车", "证据-行车"),
        "首末班与车站服务": ("服务", "证据-服务"),
        "运营保障与风险": ("保障", "证据-保障")
    }
    grouped = {"客流": [], "行车": [], "服务": [], "保障": []}
    evidence_pool = []
    seen = set()

    for result_name, (topic, prefix) in topic_map.items():
        rows = metric_result.get(result_name, {}).get("事实", [])
        ranked = sorted(rows, key=lambda x: int(x.get("优先级", 0)), reverse=True)
        index = 0
        for row in ranked:
            dedupe = (topic, row.get("来源数据组"), row.get("来源字段"), row.get("事实"))
            if dedupe in seen:
                continue
            seen.add(dedupe)
            index += 1
            item = {
                "证据编号": f"{prefix}-{index:03d}",
                "专题": topic,
                "来源数据组": row.get("来源数据组", ""),
                "来源字段": row.get("来源字段", ""),
                "事实": str(row.get("事实", ""))[:300],
                "优先级": int(row.get("优先级", 0)),
                "来源类型": "业务系统直传或代码确定性整理"
            }
            evidence_pool.append(item)
            grouped[topic].append(item)

    def dump_topic(topic):
        return json.dumps(grouped.get(topic, [])[:12], ensure_ascii=False, separators=(",", ":"))

    summary_rows = []
    for topic in ["客流", "行车", "服务", "保障"]:
        summary_rows.extend(grouped.get(topic, [])[:3])

    return {
        "evidence_pool": evidence_pool,
        "pass_evidence": dump_topic("客流"),
        "ops_evidence": dump_topic("行车"),
        "service_evidence": dump_topic("服务"),
        "guard_evidence": dump_topic("保障"),
        "summary_evidence": json.dumps(summary_rows[:12], ensure_ascii=False, separators=(",", ":"))
    }

def main(metric_result: dict, evidence_pool: list[dict]) -> dict:
    import json

    issues = []

    def evidence_ids(topic, limit=3):
        return [x.get("证据编号") for x in evidence_pool if x.get("专题") == topic][:limit]

    def add(topic, title, level, condition, scope):
        issues.append({
            "候选编号": f"问题-{len(issues) + 1:03d}",
            "专题": topic,
            "问题": title,
            "等级": level,
            "触发事实": condition,
            "建议范围": scope,
            "证据编号": evidence_ids(topic)
        })

    passenger = metric_result.get("客流及线网影响", {}).get("指标", {})
    for row in passenger.get("既有线运能匹配", []):
        if row.get("日期类型") == "工作日" and float(row.get("满载率_百分数", 0) or 0) >= 75:
            add("客流", f"{row.get('线路名称')}工作日高峰断面满载率需重点监测", "中", f"满载率{row.get('满载率_百分数')}%", "保持现有上线能力并按断面、方向滚动监测")
    for row in passenger.get("既有线断面位置变化", []):
        add("客流", f"{row.get('线路名称')}最大断面位置和方向发生变化", "中", f"由{row.get('开通前断面区间')}{row.get('开通前方向')}转移至{row.get('开通后断面区间')}{row.get('开通后方向')}", "复核方向性运力配置")

    operation = metric_result.get("行车组织", {}).get("指标", {})
    for row in operation.get("分时运行方案", []):
        if float(row.get("外围区段行车间隔_秒", 0) or 0) > 900:
            add("行车", f"{row.get('日期类型')}{row.get('时段')}外围区段服务间隔较长", "中", f"外围区段间隔{row.get('外围区段间隔显示')}", "开通初期监测乘客等待和外围客流，必要时调整交路比例")
    if operation.get("备用图车辆余量_列", 0) <= 0:
        add("行车", "备用图与计划备用车同时兑现时车辆无额外余量", "高", f"车辆余量{operation.get('备用图车辆余量_列')}列", "强化车辆状态控制和备用车快速上线")
    if operation.get("备用图司机余量_人", 0) <= 0:
        add("行车", "备用图与备班同时兑现时司机无额外余量", "高", f"司机余量{operation.get('备用图司机余量_人')}人", "复核班制、工时及备班可用性")

    service = metric_result.get("首末班与车站服务", {}).get("指标", {})
    for row in service.get("重点首班换乘衔接", []):
        if float(row.get("等待时间_秒", 0) or 0) >= 1200:
            add("服务", f"{row.get('换乘站')}首班换乘等待时间较长", "中", f"等待{row.get('等待时间_分钟')}分钟", "核查既有线分段首班车调整和换乘引导")
    max_density = service.get("最高密度车站", {})
    if max_density:
        add("服务", f"{max_density.get('车站名称')}为重点站台密度控制站", "低", f"最高预测密度{max_density.get('最高预测站台密度_人每平方米')}人/平方米", "开通初期关注集中到达和换乘路径不熟悉造成的局部积聚")

    guard = metric_result.get("运营保障与风险", {}).get("指标", {})
    if guard.get("车辆余量_列", 0) <= 0 or guard.get("司机余量_人", 0) <= 0:
        add("保障", "高客流备用图资源配置无额外机动余量", "高", f"车辆余量{guard.get('车辆余量_列')}列、司机余量{guard.get('司机余量_人')}人", "建立车辆、乘务资源日核查和异常替补机制")
    if guard.get("最低设备可用率_百分数", 100) < 100:
        add("保障", "部分设备处于开通磨合期", "中", f"最低设备可用率{guard.get('最低设备可用率_百分数')}%", "落实专业及厂家驻点、备件和降级预案")

    def dump_topic(topic):
        return json.dumps([x for x in issues if x.get("专题") == topic][:8], ensure_ascii=False, separators=(",", ":"))

    return {
        "issue_cands": issues,
        "pass_issues": dump_topic("客流"),
        "ops_issues": dump_topic("行车"),
        "service_issues": dump_topic("服务"),
        "guard_issues": dump_topic("保障")
    }

def main(
    pass_md: str,
    ops_md: str,
    service_md: str,
    guard_md: str,
    evidence_pool: list[dict],
    metric_result: dict
) -> dict:
    import json
    import re

    def clean(value):
        text = str(value or "").strip()
        if text.startswith("```"):
            text = re.sub(r"^```(?:markdown|md)?\s*", "", text)
            text = re.sub(r"\s*```$", "", text)
        return text.strip()

    def numbers(value):
        text = json.dumps(value, ensure_ascii=False) if not isinstance(value, str) else value
        return set(re.findall(r"(?<![A-Za-z])\d+(?:\.\d+)?", text))

    raw = {
        "客流": pass_md,
        "行车": ops_md,
        "服务": service_md,
        "保障": guard_md
    }
    required = {
        "客流": ["## 二、客流预测及线网影响分析"],
        "行车": ["## 三、新线行车组织方案", "## 四、既有线运输组织调整建议"],
        "服务": ["## 五、首末班车及线网衔接方案", "## 六、车站客运组织及乘客服务"],
        "保障": ["## 七、运营保障及风险控制"]
    }
    max_lengths = {"客流": 10000, "行车": 10000, "服务": 9000, "保障": 8000}
    chapters = {}
    reviews = []
    warnings = []
    hard_errors = []
    allowed_numbers = numbers(metric_result)

    for topic, value in raw.items():
        text = clean(value)
        local_errors = []
        headings = required[topic]
        if not text:
            local_errors.append(f"{topic}专题正文为空")
        elif not text.startswith(headings[0]):
            local_errors.append(f"{topic}专题首行标题错误")
        last_pos = -1
        for heading in headings:
            matches = list(re.finditer(rf"(?m)^{re.escape(heading)}\s*$", text))
            if len(matches) != 1:
                local_errors.append(f"标题必须且只能出现一次：{heading}")
            elif matches[0].start() <= last_pos:
                local_errors.append(f"{topic}专题标题顺序错误")
            else:
                last_pos = matches[0].start()
        if len(text) > max_lengths[topic]:
            local_errors.append(f"{topic}专题超过{max_lengths[topic]}字符")
        if "### 专题结论" not in text:
            local_errors.append(f"{topic}专题缺少专题结论")
        if re.search(r"证据-(?:客流|行车|服务|保障)-\d{3}", text):
            local_errors.append(f"{topic}专题正文暴露内部证据编号")
        if text.startswith("{") or text.startswith("["):
            local_errors.append(f"{topic}专题不得输出JSON")

        output_numbers = numbers(text)
        unknown = sorted(x for x in output_numbers - allowed_numbers if float(x) > 50)
        if unknown:
            warnings.append(f"{topic}专题出现需人工复核数字：{unknown[:10]}")

        marker = "### 专题结论"
        topic_summary = text.split(marker, 1)[1].strip()[:600] if marker in text else text[-600:]
        reviews.append({
            "专题": topic,
            "标题": headings,
            "字符数": len(text),
            "专题结论": topic_summary,
            "是否通过": len(local_errors) == 0
        })
        if local_errors:
            hard_errors.extend(local_errors)
        else:
            chapters[topic] = text

    ranked = sorted(evidence_pool, key=lambda x: (-int(x.get("优先级", 0)), str(x.get("证据编号", ""))))
    summary_rows = []
    selected = set()
    for topic in ["客流", "行车", "服务", "保障"]:
        for item in [x for x in ranked if x.get("专题") == topic][:3]:
            item_id = item.get("证据编号")
            if item_id not in selected:
                summary_rows.append(item)
                selected.add(item_id)

    return {
        "chapter_texts": chapters,
        "chapter_review": reviews,
        "summary_evidence": summary_rows[:12],
        "model_warns": warnings + hard_errors,
        "needs_retry": len(hard_errors) > 0
    }

def main(
    task_ctx: dict,
    chapter_texts: dict,
    summary_md: str,
    data_warns: list[str],
    model_warns: list[str]
) -> dict:
    import re

    def fail(message):
        return {
            "report_md": "",
            "report_len": 0,
            "error_msg": message,
            "workflow_status": "失败"
        }

    def split_summary(value):
        if not isinstance(value, str):
            raise TypeError("N19输出summary_md必须为String")
        text = value.strip()
        if not text:
            raise ValueError("N19输出summary_md为空")
        if text.startswith("```") or text.startswith("{") or text.startswith("["):
            raise ValueError("N19必须直接输出Markdown字符串，不能输出代码围栏或JSON")
        if len(text) > 12000:
            raise ValueError("N19输出超过12000字符")

        headings = [
            ("摘要", "## 方案摘要"),
            ("第一章", "## 一、新线基本情况"),
            ("第八章", "## 八、实施、审核与动态优化机制"),
            ("第九章", "## 九、结论")
        ]
        positions = {}
        for key, heading in headings:
            matches = list(re.finditer(rf"(?m)^{re.escape(heading)}\s*$", text))
            if len(matches) != 1:
                raise ValueError(f"标题必须且只能出现一次：{heading}")
            positions[key] = matches[0].start()
        if not (positions["摘要"] < positions["第一章"] < positions["第八章"] < positions["第九章"]):
            raise ValueError("N19四个标题顺序错误")
        if text[:positions["摘要"]].strip():
            raise ValueError("方案摘要标题前存在多余文字")
        return {
            "摘要": text[positions["摘要"]:positions["第一章"]].strip(),
            "第一章": text[positions["第一章"]:positions["第八章"]].strip(),
            "第八章": text[positions["第八章"]:positions["第九章"]].strip(),
            "第九章": text[positions["第九章"]:].strip()
        }

    try:
        summary = split_summary(summary_md)
    except Exception as exc:
        return fail(str(exc))

    required_topics = ["客流", "行车", "服务", "保障"]
    missing = [x for x in required_topics if not chapter_texts.get(x)]
    if missing:
        return fail(f"缺少或未通过校验的专题章节：{missing}")

    line_name = task_ctx.get("线路名称", "新线")
    header = (
        f"# {line_name}运营组织方案\n\n"
        f"**预测方案：** {task_ctx.get('方案名称', '')}  \n"
        f"**方案编号：** {task_ctx.get('方案编号', '')}  \n"
        f"**预测周期：** {task_ctx.get('预测开始日期', '')}至{task_ctx.get('预测结束日期', '')}  \n"
        f"**数据生成时间：** {task_ctx.get('预测生成时间', '')}"
    )
    parts = [
        header,
        summary["摘要"],
        summary["第一章"],
        chapter_texts["客流"].strip(),
        chapter_texts["行车"].strip(),
        chapter_texts["服务"].strip(),
        chapter_texts["保障"].strip(),
        summary["第八章"],
        summary["第九章"]
    ]
    report = "\n\n".join(parts).strip() + "\n"
    nonfatal_count = len(data_warns or []) + len(model_warns or [])
    status = "成功" if nonfatal_count == 0 else "成功（有告警）"
    return {
        "report_md": report,
        "report_len": len(report),
        "error_msg": "",
        "workflow_status": status
    }
